CREATE TABLE IF NOT EXISTS teams (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS email_settings (id TINYINT PRIMARY KEY,provider ENUM('GHL','SMTP') NOT NULL DEFAULT 'GHL',enabled BOOLEAN NOT NULL DEFAULT FALSE,host VARCHAR(253) NOT NULL DEFAULT '',port INT NOT NULL DEFAULT 587,security ENUM('TLS','STARTTLS','NONE') NOT NULL DEFAULT 'STARTTLS',auth_enabled BOOLEAN NOT NULL DEFAULT TRUE,username VARCHAR(254) NOT NULL DEFAULT '',password_encrypted TEXT NULL,from_email VARCHAR(254) NOT NULL DEFAULT '',from_name VARCHAR(120) NOT NULL DEFAULT 'Operations',reply_to VARCHAR(254) NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS contract_intake (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,contract_id VARCHAR(120) NOT NULL UNIQUE,opportunity_id VARCHAR(120) NOT NULL UNIQUE,client_name VARCHAR(200) NOT NULL,client_email VARCHAR(254) NOT NULL,payload JSON NOT NULL,case_id BIGINT UNSIGNED NULL,initiated_by BIGINT UNSIGNED NULL,initiated_at DATETIME NULL,received_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS category_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,category_id BIGINT UNSIGNED NOT NULL,version INT NOT NULL,fields JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(category_id,version),FOREIGN KEY(category_id) REFERENCES categories(id));
CREATE TABLE IF NOT EXISTS requirements (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,field_key VARCHAR(120) NOT NULL,definition JSON NOT NULL,value_json JSON NULL,waived BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY(case_id,field_key),FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS document_versions (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,requirement_id BIGINT UNSIGNED NOT NULL,version INT NOT NULL,original_name VARCHAR(255) NOT NULL,storage_key CHAR(36) NOT NULL,mime VARCHAR(80) NOT NULL,byte_size INT NOT NULL,sha256 CHAR(64) NOT NULL,
 status ENUM('PENDING','ACCEPTED','REJECTED') NOT NULL DEFAULT 'PENDING',reason TEXT NULL,uploaded_by BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NULL,reviewed_at DATETIME NULL,ghl_media_id VARCHAR(120) NULL,ghl_media_url TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY(requirement_id,version),FOREIGN KEY(requirement_id) REFERENCES requirements(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS case_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,actor_id BIGINT UNSIGNED NULL,action VARCHAR(100) NOT NULL,description TEXT NOT NULL,client_visible BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS tasks (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,title VARCHAR(240) NOT NULL,assigned_to BIGINT UNSIGNED NULL,due_at DATETIME NULL,status ENUM('OPEN','DONE') NOT NULL DEFAULT 'OPEN',created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,case_id BIGINT UNSIGNED NULL,event_key VARCHAR(180) NOT NULL,description TEXT NOT NULL,read_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY(user_id,event_key),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS email_outbox (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,case_id BIGINT UNSIGNED NULL,recipient_contact_id VARCHAR(120) NULL,payload_encrypted MEDIUMTEXT NOT NULL,event_key VARCHAR(180) NOT NULL UNIQUE,status ENUM('QUEUED','SENDING','SENT','FAILED','UNKNOWN') NOT NULL DEFAULT 'QUEUED',attempts INT NOT NULL DEFAULT 0,next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_error VARCHAR(500) NULL,provider_message_id VARCHAR(120) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS invitations (token_hash CHAR(64) PRIMARY KEY,case_id BIGINT UNSIGNED NOT NULL,email VARCHAR(254) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,FOREIGN KEY(case_id) REFERENCES cases(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS application_settings (id TINYINT PRIMARY KEY,settings JSON NOT NULL);
CREATE TABLE IF NOT EXISTS handoff_events (event_id VARCHAR(120) PRIMARY KEY,contract_id VARCHAR(120) NOT NULL,result VARCHAR(100) NOT NULL,case_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
